package com.portfoliolab.backend.research;
import com.portfoliolab.backend.portfolio.*;import com.portfoliolab.backend.market.*;import java.math.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class RiskLabTests {
 PortfolioRepository portfolios=mock(PortfolioRepository.class);PortfolioQueryService holdings=mock(PortfolioQueryService.class);MarketService market=mock(MarketService.class);ResearchHistoryStore history=mock(ResearchHistoryStore.class);Portfolio portfolio=mock(Portfolio.class);RiskLabService service=new RiskLabService(portfolios,holdings,market,history);
 @BeforeEach void setup(){when(portfolios.findById(1L)).thenReturn(Optional.of(portfolio));when(portfolio.getCashBalance()).thenReturn(new BigDecimal("100"));when(portfolio.getCurrency()).thenReturn("INR");when(market.getCurrentPrices()).thenReturn(List.of(new MarketPrice("ALPHA",new BigDecimal("100"),"INR",Instant.now())));when(holdings.getHoldings(1L)).thenReturn(List.of(new HoldingResponse(5L,"ALPHA","Fictional",new BigDecimal("2"),new BigDecimal("90"),new BigDecimal("90"),new BigDecimal("180"),BigDecimal.ZERO,"INR",BigDecimal.ONE,new BigDecimal("180"),"INR",new BigDecimal("180"),BigDecimal.ZERO)));}
 @Test void exposureMatchesCurrentQuoteAndHistoricalCost(){var r=service.evaluate(1,null);assertEquals(0,r.marketValue().compareTo(new BigDecimal("300")));assertEquals(0,r.unrealizedGainLoss().compareTo(new BigDecimal("20")));assertEquals(1,r.assetHhi());assertNull(r.metrics().historicalVolatilityPct());verify(history,never()).ingest(anyLong(),anyString(),any(),any());verify(portfolio,never()).setCashBalance(any());verify(portfolios,never()).save(any());}
 @Test void positiveNegativeAndOverrides(){for(int s:new int[]{-100,-10,0,10,100}){var r=service.evaluate(1,new RiskLabService.Scenario(BigDecimal.valueOf(s),Map.of()));assertEquals(0,r.projectedValue().compareTo(new BigDecimal("300").add(BigDecimal.valueOf(2L*s))));}var r=service.evaluate(1,new RiskLabService.Scenario(BigDecimal.TEN,Map.of(5L,new BigDecimal("-20"))));assertEquals(0,r.projectedValue().compareTo(new BigDecimal("260")));}
 @Test void missingPriceDoesNotInventZero(){when(market.getCurrentPrices()).thenReturn(List.of());var r=service.evaluate(1,null);assertNull(r.marketValue());assertNull(r.projectedValue());assertNull(r.positions().getFirst().marketValue());}
 @Test void emptyPortfolioAndZeroDenominator(){when(holdings.getHoldings(1L)).thenReturn(List.of());when(portfolio.getCashBalance()).thenReturn(BigDecimal.ZERO);var r=service.evaluate(1,null);assertEquals(0,r.marketValue().signum());assertNull(r.cashAllocationPct());assertNull(r.percentageChange());}
 @Test void scopingAndInvalidShocks(){assertThrows(RuntimeException.class,()->service.evaluate(2,null));verify(portfolios,never()).findById(2L);assertThrows(RuntimeException.class,()->service.evaluate(1,new RiskLabService.Scenario(new BigDecimal("-101"),Map.of())));assertThrows(RuntimeException.class,()->service.evaluate(1,new RiskLabService.Scenario(BigDecimal.ZERO,Map.of(999L,BigDecimal.TEN))));}
 @Test void sufficientHistoryProducesMetricsWithoutWrites(){var to=LocalDate.now(ZoneOffset.UTC);var from=to.minusDays(90);var candles=new java.util.ArrayList<ResearchHistoryStore.Candle>();for(int i=0;i<90;i++){var price=BigDecimal.valueOf(100+i);candles.add(new ResearchHistoryStore.Candle(from.plusDays(i).atStartOfDay(ZoneOffset.UTC).toInstant(),price,price,price,price,100));}when(history.read(5,from,to)).thenReturn(candles);var r=service.evaluate(1,null);assertNotNull(r.metrics().historicalVolatilityPct());assertEquals(0,r.metrics().maximumDrawdownPct());assertEquals(90,r.metrics().observations());verify(history,never()).ingest(anyLong(),anyString(),any(),any());}
 @Test void scenarioTransactionIsReadOnly() throws Exception{assertTrue(RiskLabService.class.getMethod("evaluate",long.class,RiskLabService.Scenario.class).getAnnotation(org.springframework.transaction.annotation.Transactional.class).readOnly());}
}
